#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# One-time maintainer setup for signed Controller releases (ADR 0010): creates the
# release key, publishes the repository with a fresh history if it is still private,
# stores the signing secret, and cuts the first release. Safe to re-run: each stage
# detects what is already done.

OWNER=H3atman
NAME=openpiso-wifi
ARCHIVE=openpiso-wifi-private
PUB=controller/release.pub
SEED=""

die() { printf '\n  %s✗ %s%s\n\n' "$YELLOW" "$1" "$RESET"; exit 1; }

# repo_state prints public, private, or absent for OWNER/NAME. A renamed repo
# still answers under its old name, so the returned name is compared too.
repo_state() {
  local out
  out=$(gh repo view "$OWNER/$NAME" --json nameWithOwner,visibility \
    --jq '.nameWithOwner + " " + .visibility' 2>/dev/null) || { echo absent; return; }
  case "$out" in
    "$OWNER/$NAME PUBLIC") echo public ;;
    "$OWNER/$NAME "*)      echo private ;;
    *)                     echo absent ;;
  esac
}

run_wizard() {

TOTAL_STAGES=6

cd "$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
export PATH="$HOME/.local/go/bin:$PATH"   # the pre-commit hook needs gofmt
command -v go >/dev/null 2>&1 || die "Go is not installed (looked on PATH and in ~/.local/go/bin)."
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || die "gh is not installed or not logged in: run 'gh auth login'."
[[ "$(git branch --show-current)" == main ]] || die "Run this from the main branch, after the updater work is merged."
[[ -z "$(git status --porcelain | grep -v " $PUB\$" || true)" ]] || die "The working tree is not clean: commit or stash first."
[[ -f .github/workflows/release.yml && -f LICENSE ]] || die "main has no release workflow or LICENSE yet: merge the updater branch first."

banner "OpenPiso release setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Release key"
say "Every Controller trusts exactly one Ed25519 key. CI signs each release with"
say "the private half; the public half is compiled into the binary."
echo
if [[ -s "$PUB" ]]; then
  say "A public key already exists in $PUB, so this install base already trusts it."
  step "Find the private key you saved when it was created."
  ask_secret SEED "Paste the private key (hidden):"
  [[ -n "$SEED" ]] || die "No private key given."
  note "It is checked against $PUB by the release workflow before anything is published."
else
  keys=$(cd controller && go run ./cmd/releasetool keygen)
  SEED=$(sed -n 's/^private=//p' <<<"$keys")
  public=$(sed -n 's/^public=//p' <<<"$keys")
  [[ -n "$SEED" && -n "$public" ]] || die "releasetool keygen printed no key."
  printf '%s\n' "$public" > "$PUB"
  printf '  %s✓ wrote%s public key → %s\n\n' "$GREEN" "$RESET" "$PUB"
  warn "This is the private key. It is shown once and stored nowhere on this PC."
  printf '\n      %s%s%s\n\n' "$BOLD" "$SEED" "$RESET"
  step "Save it in your password manager now (name it 'OpenPiso release signing key')."
  say "If it is lost, no shop can be updated again without a manual reinstall."
  say "If it leaks, whoever has it can run code as root on every shop."
  echo
  check=""
  ask_secret check "Paste it back from your password manager to prove it is saved (hidden):"
  [[ "$check" == "$SEED" ]] || { rm -f "$PUB"; die "That did not match. Nothing was kept: run the wizard again."; }
fi
pause "Press Enter to clear the screen and continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Commit the public key"
if [[ -z "$(git status --porcelain -- "$PUB")" ]]; then
  note "$PUB is already committed."
else
  say "This commits $PUB to main so every build compiles the key in."
  confirm "Commit $PUB to main?" || die "Stopped. $PUB is written but not committed."
  git add "$PUB"
  git commit -q -m "Controller: add the release public key"
  printf '  %s✓ committed%s %s\n' "$GREEN" "$RESET" "$PUB"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Check what becomes public"
state=$(repo_state)
if [[ "$state" == public ]]; then
  note "$OWNER/$NAME is already public: nothing to check."
else
  say "The public repository starts as ONE commit holding the current files of main."
  say "No earlier history, branches, pull requests, or issues go with it."
  echo
  leaks=$(git grep -nI -e "/home/$USER" HEAD -- . | head -n 5 || true)
  [[ -z "$leaks" ]] || { printf '%s\n' "$leaks"; die "Local paths are still in tracked files. Scrub them, commit, and re-run."; }
  printf '  %s✓%s no local home-directory paths in tracked files\n' "$GREEN" "$RESET"
  printf '  %s✓%s %s files, %s\n' "$GREEN" "$RESET" "$(git ls-files | wc -l)" "$(git count-objects -vH | sed -n 's/^size-pack: //p') packed"
  echo
  say "The commit will be signed off publicly as:"
  printf '\n      %s%s <%s>%s\n\n' "$BOLD" "$(git config user.name)" "$(git config user.email)" "$RESET"
  step "If that email should stay private, stop here, set a GitHub noreply address with"
  say "  git config user.email ID+USERNAME@users.noreply.github.com"
  say "(shown at the page below), and re-run."
  open_url "https://github.com/settings/emails"
  confirm "Publish under that name and email?" || die "Stopped before anything was published."
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Publish the repository"
state=$(repo_state)
if [[ "$state" == public ]]; then
  note "$OWNER/$NAME is already public."
  # Never push the private history: main must build on what the public repo has.
  git fetch -q origin
  git merge-base --is-ancestor origin/main main 2>/dev/null \
    || die "Local main does not build on the public main. Check 'git remote -v' and 'git log origin/main' before pushing anything."
  if [[ -n "$(git log origin/main..main --oneline 2>/dev/null)" ]]; then
    confirm "Push main to $OWNER/$NAME?" || die "Stopped. main has unpushed commits."
    git push -q origin main
    printf '  %s✓ pushed%s main\n' "$GREEN" "$RESET"
  fi
else
  say "Two things happen here, in this order:"
  step "Today's private repository is renamed to $OWNER/$ARCHIVE and stays private."
  say "  It keeps the full history, all branches, pull requests, and issues."
  step "A new PUBLIC $OWNER/$NAME is created and main is pushed to it as one commit."
  echo
  warn "Open issues and pull requests stay behind in $ARCHIVE. GitHub cannot move"
  say "  issues from a private repository to a public one: re-file the ones you want public."
  warn "Going public cannot be cleanly undone: clones and caches may keep what was pushed."
  echo
  if [[ "$state" == private ]]; then
    confirm "Rename the private repository to $OWNER/$ARCHIVE?" || die "Stopped. Nothing was changed on GitHub."
    gh repo rename "$ARCHIVE" --repo "$OWNER/$NAME" --yes >/dev/null
    printf '  %s✓ renamed%s private repository → %s/%s\n' "$GREEN" "$RESET" "$OWNER" "$ARCHIVE"
  else
    note "The private repository was already renamed."
  fi
  if ! git remote | grep -qx private; then
    url=$(git remote get-url origin)
    git remote rename origin private
    git remote set-url private "${url/$NAME/$ARCHIVE}"
    git push -q private main
    printf '  %s✓%s remote "private" → %s, main pushed there\n' "$GREEN" "$RESET" "$ARCHIVE"
  fi
  url=$(git remote get-url private)
  confirm "Create the PUBLIC repository $OWNER/$NAME and push main as one commit?" \
    || die "Stopped. The private repository is renamed; re-run to continue."
  gh repo create "$OWNER/$NAME" --public --disable-wiki \
    --description "Open-source piso WiFi: a Controller for MikroTik HotSpot shops and coin Vendos" >/dev/null
  git remote add origin "${url/$ARCHIVE/$NAME}"
  clean=$(git commit-tree "HEAD^{tree}" -m "Initial public release")
  git push -q origin "$clean:refs/heads/main"
  # Keep the old history locally as private-main; main now follows the public repo.
  git branch -m main private-main
  git branch -q --set-upstream-to=private/main private-main
  git switch -q -c main "$clean"
  git fetch -q origin
  git branch -q --set-upstream-to=origin/main main
  printf '  %s✓ published%s https://github.com/%s/%s\n' "$GREEN" "$RESET" "$OWNER" "$NAME"
  note "Your full history is on the local branch private-main and in $OWNER/$ARCHIVE."
  open_url "https://github.com/$OWNER/$NAME"
fi
export GH_REPO="$OWNER/$NAME"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Signing secret"
say "The release workflow reads the private key from the Actions secret"
say "RELEASE_SIGNING_KEY on $OWNER/$NAME. GitHub never shows it again after this."
echo
set_secret RELEASE_SIGNING_KEY "$SEED"
SEED=""
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First release"
say "Pushing a vMAJOR.MINOR.PATCH tag on main builds, signs, and publishes a release."
say "Installed Controllers see it at their next daily check."
echo
latest=$(gh release view --json tagName --jq .tagName 2>/dev/null || true)
if [[ -n "$latest" ]]; then
  note "Latest published release: $latest. Nothing to do; cut later ones with"
  note "  git tag vX.Y.Z && git push origin vX.Y.Z"
else
  RELEASE_VERSION=""
  ask RELEASE_VERSION "Version for the first release (e.g. v0.1.0):"
  [[ "$RELEASE_VERSION" =~ ^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$ ]] \
    || die "'$RELEASE_VERSION' is not vMAJOR.MINOR.PATCH."
  if confirm "Tag main as $RELEASE_VERSION and publish it to every user of $OWNER/$NAME?"; then
    git tag "$RELEASE_VERSION"
    git push -q origin "$RELEASE_VERSION"
    say "Waiting for the Release workflow to start..."
    run=""
    for _ in {1..30}; do
      run=$(gh run list --workflow release.yml --commit "$(git rev-parse HEAD)" --limit 1 \
        --json databaseId --jq '.[0].databaseId // empty' 2>/dev/null || true)
      [[ -n "$run" ]] && break
      sleep 2
    done
    [[ -n "$run" ]] || die "The Release workflow did not start: check https://github.com/$OWNER/$NAME/actions"
    gh run watch "$run" --exit-status || die "The Release workflow failed: gh run view $run --log-failed"
    dl=$(mktemp -d)
    gh release download "$RELEASE_VERSION" --dir "$dl" --pattern 'openpiso-linux-*' --pattern 'release.json*'
    (cd controller && go run ./cmd/releasetool verify -dir "$dl" -pub release.pub) \
      || { rm -rf "$dl"; die "The published release does not verify against $PUB."; }
    rm -rf "$dl"
    printf '  %s✓ %s is published and verifies against %s%s\n' "$GREEN" "$RELEASE_VERSION" "$PUB" "$RESET"
    open_url "https://github.com/$OWNER/$NAME/releases/tag/$RELEASE_VERSION"
  else
    SKIPPED+=("first release (git tag vX.Y.Z && git push origin vX.Y.Z)")
  fi
fi
pause

finish
}

run_wizard "$@"; exit
